def debug_iteration(grid, debug_layer=0):
    """Single iteration with careful debug."""
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                region_cells = []

                queue = [(r, c)]
                visited.add((r, c))

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    region_cells.append((curr_r, curr_c))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr = curr_r + dr
                        nc = curr_c + dc

                        # GOTCHA: maybe grid[0] is not a list?
                        try:
                            ncols = len(grid[0])
                        except:
                            ncols = None
                        if nc < 0 or nc >= ncols:
                            continue
                        if nr < 0 or nr >= len(grid):
                            continue
                        # NOW safe
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

    return regions, len(regions)

